import {ground,groundStyle,gardenScenery} from './garden-space.mjs?art=13';
import {creatureArt} from './growth-view.mjs?art=13';
import {COLS,ROWS,FURNITURE,inventory,openCell} from './garden.mjs?art=13';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const drawings={
 bench:'<path fill="#66472f" d="M7 27h4v16H7zm29-4h4v16h-4z"/><path fill="#976137" d="M4 10l32-6 8 4v18l-32 6-8-4z"/><path fill="#d4a36a" d="M7 11l29-5 5 3-29 6zm0 8 29-5 5 3-29 6z"/><path fill="#bb854f" d="M2 28l32-6 12 6-32 8z"/><path fill="#e5b77c" d="M5 28l29-5 8 4-29 6z"/><path fill="#755033" d="M14 36l32-8v5l-32 8z"/>',
 pot:'<path fill="#8a5134" d="M14 29l20-3 4 5-4 13-15 3-5-6z"/><path fill="#d99159" d="M14 29l9 4v12l-5-3z"/><path fill="#e9b47a" d="M11 28l21-5 9 5-21 5z"/><path fill="#654b35" d="M17 28l15-3 4 3-15 3z"/><path fill="#477b48" d="M23 13h3v15h-3zM12 18h11v6h-7zm14-4h11v6H26z"/><path fill="#fff2cc" d="M20 4h8v4h5v8h-6v5h-8v-5h-5V8h6z"/><path fill="#e7b64f" d="M21 9h6v6h-6z"/>',
 cushion:'<path fill="#b17b39" d="M3 29l25-13 17 10v9L20 47 3 37z"/><path fill="#f1c668" d="M3 27l25-13 17 10v8L20 44 3 34z"/><path fill="#ffe3a0" d="M8 27l20-10 11 7-20 11z"/><path fill="#d9a74f" d="M19 35l23-11v7L19 42z"/>',
 table:'<path fill="#71523a" d="M11 25h27v17l-11 5-16-6z"/><path fill="#a47748" d="M13 26h5v14h-5zm11 3h5v15h-5z"/><path fill="#966940" d="M3 18l13-8h18l12 8v12l-12 8H16L3 30z"/><path fill="#e0b980" d="M3 18l13-8h18l12 8v7l-12 8H16L3 25z"/><path fill="none" stroke="#b58a58" stroke-width="2" d="M12 19l7-4h12l7 4v4l-7 5H19l-7-5zm8 1h10v3H20z"/>'
};
export function furnitureArt(kind){return `<svg viewBox="0 0 48 48" aria-hidden="true" shape-rendering="crispEdges">${drawings[kind]||drawings.pot}</svg>`}
export function gardenContent(state,records,placements,selected,loaded,error,page=0,more=false){
 const owned=inventory(state),shown=records.slice(page*20,(page+1)*20),find=state.gardenLastFind;
 return `<div class="section-head"><div><div class="eyebrow">POCKET GARDEN</div><h2>🌿 みんなの庭</h2><p>育ったともだちが集まる、きみだけの庭。</p></div><span class="pill">${records.length}${more?'＋':''}匹のともだち</span></div>${error?`<div class="error" role="alert">${esc(error)} <button data-action="gardenRetry">もう一度読みこむ</button></div>`:''}<p class="garden-help" role="status">${!loaded?'庭を読みこんでいます…':selected?`${esc(FURNITURE[owned[selected]])}を置く場所をタップしてね。`:'庭は指でスクロールできるよ。家具やともだちをタップしてみよう。'}</p><div class="garden-scroll" tabindex="0" aria-label="広い庭。上下左右にスクロールできます"><div class="garden-world ${selected?'garden-editing':''}">${gardenScenery()}${selected&&loaded?Array.from({length:COLS*ROWS},(_,i)=>{const x=i%COLS,y=Math.floor(i/COLS);return openCell(x,y)?`<button class="garden-cell" data-action="gardenPlace" data-id="${x},${y}" style="left:${ground(x,y).x-24}px;top:${ground(x,y).y-20}px" aria-label="横${x}、縦${y}に置く"></button>`:''}).join(''):''}${Object.entries(placements).filter(([id,p])=>owned[id]&&openCell(p.x,p.y)).map(([id,p])=>`<button class="garden-furniture ${id===selected?'selected':''}" style="${groundStyle(p.x,p.y)}" data-action="gardenSelect" data-id="${esc(id)}" aria-label="${esc(FURNITURE[owned[id]])}を動かす">${furnitureArt(owned[id])}</button>`).join('')}<div class="garden-pets">${shown.map(r=>`<button class="garden-pet" data-action="gardenPet" data-id="${esc(r.cycleId)}" aria-label="${esc(r.name)}の思い出">${creatureArt(r.characterId,4)}<span class="pet-mood" aria-hidden="true"></span></button>`).join('')}</div></div></div>${loaded&&!records.length?'<div class="notice">最終進化したともだちが、ここに遊びに来るよ。先に家具を置いて、迎える準備をしよう！</div>':''}${records.length>20?`<div class="actions garden-pages"><button data-action="gardenPrev" ${page===0?'disabled':''}>前の仲間</button><span>${page+1} / ${Math.ceil(records.length/20)}</span><button data-action="gardenNext" ${(page+1)*20>=records.length?'disabled':''}>次の仲間</button></div>`:''}${more?'<button data-action="growthMore">もっと仲間を読みこむ</button>':''}<section class="garden-bag"><div class="section-head"><h3>ひろったもの</h3><span class="pill">${Object.keys(owned).length}こ</span></div>${find?`<p>🎁 ともだちが「${esc(FURNITURE[find.kind])}」をみつけたよ！</p>`:''}<div class="garden-inventory">${Object.entries(owned).map(([id,kind])=>`<button data-action="gardenSelect" data-id="${esc(id)}" aria-pressed="${id===selected}" ${!loaded||error?'disabled':''}>${furnitureArt(kind)}<span>${esc(FURNITURE[kind])}</span><small>${placements[id]?'庭にある':'おけるよ'}</small></button>`).join('')}</div>${selected?`<div class="actions"><button data-action="gardenCancel">やめる</button>${placements[selected]?'<button data-action="gardenPack">しまう</button>':''}</div>`:''}<p class="footer-note">はじめの家具は4こ。育った仲間ができたら、おてつだい3回の承認で家具を1こみつけるよ。みつけられる家具は60こまで。何度でも置き直せます。</p></section>`;
}
let previousPositions=new Map();
export function animateGarden(root,placements){
 if(!root)return ()=>{};const pets=[...root.querySelectorAll('.garden-pet')],used=new Set(),blocked=new Set(Object.values(placements).map(p=>`${p.x},${p.y}`));
 const free=(x,y)=>openCell(x,y)&&!blocked.has(`${x},${y}`)&&!used.has(`${x},${y}`);
 const positions=pets.map((pet,i)=>{const old=previousPositions.get(pet.dataset.id);let x=old?.x,y=old?.y;if(!free(x,y)){for(let n=0;n<180;n++){const a=1+(i*4+2+n)%18,b=3+Math.floor((i*4+n)/18)%6;if(free(a,b)){x=a;y=b;break}}}used.add(`${x},${y}`);pet.style.cssText=groundStyle(x,y);return {x,y,rest:0}});
 previousPositions=new Map(pets.map((pet,i)=>[pet.dataset.id,positions[i]]));
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return ()=>{};
 const timer=setInterval(()=>pets.forEach((pet,i)=>{const p=positions[i];pet.classList.remove('garden-stepping','celebrate');if(p.rest>0){p.rest--;return}pet.querySelector('.pet-mood').textContent='';used.delete(`${p.x},${p.y}`);const [dx,dy]=[[1,0],[-1,0],[0,1],[0,-1]][Math.floor(Math.random()*4)];if(free(p.x+dx,p.y+dy)){p.x+=dx;p.y+=dy;pet.classList.add('garden-stepping')}used.add(`${p.x},${p.y}`);pet.style.cssText=groundStyle(p.x,p.y);const near=Object.values(placements).find(f=>Math.abs(f.x-p.x)+Math.abs(f.y-p.y)===1);if(near||Math.random()<.12){p.rest=3;pet.querySelector('.pet-mood').textContent=near?.kind==='cushion'?'Zzz':near?'♪':'…';if(near&&near.kind!=='cushion')pet.classList.add('celebrate')}}),1200);
 return ()=>clearInterval(timer);
}
